import{_ as o,P as s,I as n,g as i,d as t,l as r,k as l,j as c}from"./chunks/framework.CjoWWfVe.js";const k=JSON.parse('{"title":"PRO: Multi-Workspaces & Personal Finance","description":"Managing multiple business entities in a single application, global unified backups, and revolutionary automatic personal expenditure tracking.","frontmatter":{"title":"PRO: Multi-Workspaces & Personal Finance","description":"Managing multiple business entities in a single application, global unified backups, and revolutionary automatic personal expenditure tracking.","order":15},"headers":[],"relativePath":"docs/spaces/moy-kapital/pro-mode.md","filePath":"docs/spaces/moy-kapital/pro-mode.md"}'),d={name:"docs/spaces/moy-kapital/pro-mode.md"},p={id:"pro-mode-an-ecosystem-for-scaling",tabindex:"-1"};function u(h,e,m,g,y,f){const a=s("DocIcon");return n(),i("div",null,[t("h1",p,[r(a,{name:"pro"}),e[0]||(e[0]=l(" PRO Mode: An Ecosystem for Scaling ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#pro-mode-an-ecosystem-for-scaling","aria-label":'Permalink to "<DocIcon name="pro" /> PRO Mode: An Ecosystem for Scaling"'},"​",-1))]),e[2]||(e[2]=c('<p><strong>PRO Mode</strong> is the premium architecture of OmniCraft ERP, turning a local application from a single-workshop tracker into a comprehensive <strong>capital management ecosystem</strong>.</p><p>This mode introduces two major features:</p><ol><li><strong>Multi-Workspaces:</strong> Managing multiple independent business entities with completely isolated databases.</li><li><strong>Global &quot;My Capital&quot; Tab:</strong> Automatic tracking of personal finances via a mathematical delta, eliminating the need to log every coffee receipt.</li></ol><div class="info custom-block"><p class="custom-block-title">How to Activate PRO?</p><p>PRO mode is activated by a flag in your license key. As soon as a <code>Pro</code> license key is entered into the <strong>Settings</strong> tab, the program instantly unlocks the sliding side panel (Drawer) and the global consolidation tools.</p></div><hr><h2 id="multi-workspaces" tabindex="-1">Multi-Workspaces <a class="header-anchor" href="#multi-workspaces" aria-label="Permalink to &quot;Multi-Workspaces&quot;">​</a></h2><p>Many craftsmen eventually launch adjacent projects: their main leather workshop, selling digital PDF patterns/templates, hosting classes, or offering repair services. Mixing all of this into a single database is a poor idea: different currencies, varying markups, separate warehouses, and completely different economics.</p><p>PRO mode allows you to create <strong>an unlimited number of isolated workspaces</strong>. Each workspace is a complete, separate SQLite database file with its own directories, product recipes, stock, and transaction histories.</p><h3 id="how-it-works-drawer-ui" tabindex="-1">How It Works (Drawer UI) <a class="header-anchor" href="#how-it-works-drawer-ui" aria-label="Permalink to &quot;How It Works (Drawer UI)&quot;">​</a></h3><p>A <strong>&quot;Workspaces &amp; Modules&quot;</strong> button appears in the top-right corner of the window. Clicking it slides open the right side panel (Navigation Drawer), which becomes your primary dispatch console.</p><p>The top section of the panel displays a list of all your created workspaces:</p><ul><li>🟢 <strong>Green Icon:</strong> The current active workspace whose data is currently displayed on your screen.</li><li>⚪ <strong>Grey Icon:</strong> Your other registered databases. Click them to switch instantly.</li></ul><p>Upon switching, the program replaces the active database path on the fly. The entire interface (Workshop, Calculator, Cash Flow tabs, etc.) reloads immediately, pulling up the records, stock, and analytics of the selected business.</p><h3 id="creating-a-new-workspace" tabindex="-1">Creating a New Workspace <a class="header-anchor" href="#creating-a-new-workspace" aria-label="Permalink to &quot;Creating a New Workspace&quot;">​</a></h3><p>At the bottom of the list is an <strong>&quot;Add Workspace&quot;</strong> button. Clicking it opens a dialog where you enter a clear name (for example, <em>“Patterns &amp; Digital”</em> or <em>“Leather Repairs”</em>).</p><p>The program automatically:</p><ol><li>Generates a unique ID and creates a new physical database file in your secure system folder.</li><li>Initializes all necessary tables within it (Stock, Workbench, Cash Flow, Capital, etc.).</li><li>Registers the workspace in the global <code>workspaces.json</code> registry.</li></ol><div class="tip custom-block"><p class="custom-block-title">Data Isolation</p><p>Workspaces are completely independent. Each business has its own master labor rate, global markup, overhead cost categories, and raw material stock. You can manage one business in Dollars and another in Euros, simply by changing the accounting currency in the settings of that specific workspace.</p></div><hr><h2 id="unified-global-backup" tabindex="-1">Unified Global Backup <a class="header-anchor" href="#unified-global-backup" aria-label="Permalink to &quot;Unified Global Backup&quot;">​</a></h2><p>In PRO mode, the backup system scales up. Instead of exporting each database individually, the program packages <strong>absolutely everything</strong> into a single ZIP archive:</p><ul><li>🗃️ The workspaces registry (<code>workspaces.json</code>).</li><li>📦 The default database (<code>omnicraft_erp.db</code>).</li><li>📁 The entire <code>workspaces/</code> directory containing all your additional businesses.</li><li>💳 The global personal finance database (<code>personal_finance.db</code>).</li></ul><p>This means that to completely transfer your ecosystem to a new computer or to create a reliable backup copy, you only need to perform <strong>a single click</strong> in the <code>File ➔ Export Data</code> menu.</p><hr><h2 id="global-my-capital-tab-personal-finance" tabindex="-1">Global &quot;My Capital&quot; Tab (Personal Finance) <a class="header-anchor" href="#global-my-capital-tab-personal-finance" aria-label="Permalink to &quot;Global &quot;My Capital&quot; Tab (Personal Finance)&quot;">​</a></h2><p>This is, perhaps, the most innovative feature of OmniCraft ERP. It solves the biggest headache of any entrepreneur: <strong>how to track personal money without turning into an accountant who logs every loaf of bread in a spreadsheet?</strong></p><p>In PRO mode, a prominent <strong>&quot;My Capital&quot;</strong> button appears in the side panel. Clicking it hides the standard business tabs and opens a global consolidation dashboard organized into a clean 5-tab funnel:</p><h3 id="_1-accounts-investments-liquidity-hub" tabindex="-1">1. Accounts &amp; Investments (Liquidity Hub) <a class="header-anchor" href="#_1-accounts-investments-liquidity-hub" aria-label="Permalink to &quot;1. Accounts &amp; Investments (Liquidity Hub)&quot;">​</a></h3><p>A unified center for managing liquidity outside business operations, united by a compact segmented switcher:</p><ul><li><strong>Bank Accounts &amp; Cards:</strong> debit and credit cards, cash in wallets, savings accounts, deposits, and currency holdings. To update a balance, simply click the pencil icon and enter the actual amount — the program records the delta automatically.</li><li><strong>Investment Portfolio:</strong> securities (stocks, bonds, ETFs), equity in external businesses, and partner loans with total return tracking and segmented filtering.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Where to track stablecoins and USDT?</p><p>Settlement stablecoins (USDT, USDC) and crypto wallets used as payment methods or liquidity reserves are best recorded in the <strong>&quot;Bank Accounts &amp; Cards&quot;</strong> tab as foreign currency accounts. The <strong>&quot;Investment Portfolio&quot;</strong> tab is designed for return-generating assets (stocks, bonds, funds, business equity, partner loans) with capital appreciation tracking.</p></div><h3 id="_2-property-materials-unified-tangible-asset-registry" tabindex="-1">2. Property &amp; Materials (Unified Tangible Asset Registry) <a class="header-anchor" href="#_2-property-materials-unified-tangible-asset-registry" aria-label="Permalink to &quot;2. Property &amp; Materials (Unified Tangible Asset Registry)&quot;">​</a></h3><p>The central registry of all physical resources of the master with 4 summary KPI cards (<code>All Property &amp; Materials</code>, <code>Real Estate &amp; Vehicles</code>, <code>Equipment &amp; Machinery</code>, <code>Materials &amp; Inventory</code>) and a 4-segment filter:</p><ul><li><strong>Real Estate &amp; Vehicles:</strong> personal apartments, land, work and personal vehicles, and valuables with savings goal tracking.</li><li><strong>Equipment &amp; Machinery:</strong> workshop machinery, tools, and work assets with dynamic depreciation and precise ownership share configuration.</li><li><strong>Materials &amp; Inventory:</strong> warehouse stocks of raw materials, hardware, and consumables evaluated via MAC across all registered storages.</li><li><strong>Ownership Shares (3-Way Hamilton Balancing):</strong> the chart icon opens the allocation editor: $\\text{Personal} + \\text{Production} + \\text{Services} = 100.00%$ ($10,000\\text{ bp}$) with instant automatic largest-remainder rebalancing.</li><li><strong>Deletion Guardrails:</strong> the delete button verifies whether an operational history exists (cash flow transactions, material write-offs, production batches, equipment maintenance). If the item participated in actual operations, hard deletion is blocked to prevent cash flow gaps, and the program offers safe retirement to Archive (<code>Sold</code>, <code>Scrapped / Worn Out</code>, <code>Gifted / Decommissioned</code>).</li><li><strong>Duplicate &amp; Collision Guard:</strong> audit duplicate entries and ownership share imbalances.</li></ul><h3 id="_3-key-operations" tabindex="-1">3. Key Operations <a class="header-anchor" href="#_3-key-operations" aria-label="Permalink to &quot;3. Key Operations&quot;">​</a></h3><p>A ledger for recording only <strong>significant</strong> external cash flows that cannot be ignored:</p><ul><li><em>External Income:</em> Salary from employment, one-off freelance work, dividends, large gifts.</li><li><em>Targeted Expenses:</em> Major purchases, education payments, medical services, debt repayments.</li></ul><h3 id="_4-my-capital-summary-dashboard" tabindex="-1">4. My Capital (Summary Dashboard) <a class="header-anchor" href="#_4-my-capital-summary-dashboard" aria-label="Permalink to &quot;4. My Capital (Summary Dashboard)&quot;">​</a></h3><p>The heart of the space. Here, the program merges the data from all your business workspaces and personal accounts to calculate key indicators:</p><div class="tip custom-block"><p class="custom-block-title">First Launch Onboarding</p><p>If personal accounts and workspaces have not yet been formed, the screen welcomes you with an intuitive first-start card (Empty State) featuring a button to quickly add your first account and an option to explore the demonstration mode.</p></div><ul><li><strong>Consolidated Capital Structure (Net Worth):</strong> 4-pillar breakdown: <ol><li>💳 <strong>Accounts (Cash)</strong> — liquid money across bank cards, cash holdings, and deposits.</li><li>📈 <strong>Investments</strong> — stocks, bonds, funds, and cryptocurrency.</li><li>🏠 <strong>Personal Assets</strong> — real estate, vehicles, and valuables.</li><li>🏭 <strong>Workspace Property</strong> — cumulative book value of equipment, machinery, tools, vehicles, and warehouse inventory across all workspaces.</li></ol></li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">Metric</th><th style="text-align:left;">What It Means</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>💎 Net Worth (Total Capital)</strong></td><td style="text-align:left;">Sum of all 4 capital pillars (Accounts + Investments + Personal Assets + Workspace Property). Your cumulative wealth at the current second.</td></tr><tr><td style="text-align:left;"><strong>💰 Earned in Businesses</strong></td><td style="text-align:left;">Consolidated net profit (P&amp;L) from all active workspaces over all time.</td></tr><tr><td style="text-align:left;"><strong>📈 External Income / Accumulated</strong></td><td style="text-align:left;">The sum of all key personal income entries not related to your businesses.</td></tr><tr><td style="text-align:left;"><strong>🔍 Free Expenses on Life</strong></td><td style="text-align:left;">That &quot;magical&quot; figure (see below).</td></tr></tbody></table><h4 id="the-magical-formula-of-free-expenses" tabindex="-1">The Magical Formula of Free Expenses <a class="header-anchor" href="#the-magical-formula-of-free-expenses" aria-label="Permalink to &quot;The Magical Formula of Free Expenses&quot;">​</a></h4><p>How does the program know how much you spent on life (food, fuel, coffee, clothing) if you didn&#39;t log those receipts? It calculates them <strong>from the reverse</strong>, using your capital delta:</p><p>$$\\text{Free Expenses} = \\text{Business Profit} + \\text{External Income} - \\text{Key Personal Expenses} - \\text{Actual Capital Growth}$$</p><p><strong>How it works in practice:</strong></p><ol><li>The program sees that your businesses generated <strong>$10,000</strong> in net profit.</li><li>You received a salary at your day job of <strong>$5,000</strong> (recorded as External Income).</li><li>You made a major payment of <strong>$3,000</strong> (recorded as a Key Expense).</li><li><em>Theoretically</em>, your money should have increased by <strong>$12,000</strong> (<code>$10,000</code> + <code>$5,000</code> - <code>$3,000</code>).</li><li>But the program checks your real bank accounts and sees that your total balance only grew by <strong>$4,000</strong>.</li><li><strong>Conclusion:</strong> You spent <strong>$8,000</strong> (<code>$12,000</code> - <code>$4,000</code>) on daily life. The program will display this exact figure in the &quot;Free Expenses on Life&quot; block.</li></ol><div class="tip custom-block"><p class="custom-block-title">The &quot;No-Friction Accounting&quot; Philosophy</p><p>This approach completely eliminates personal budget micromanagement. You do not need to scan supermarket receipts. The program acts as an honest mirror: it shows the volume of cash that &quot;dissolves&quot; into daily life, allowing you to evaluate your true standard of living and adjust financial goals based on solid mathematical facts.</p></div><h3 id="_5-analytics" tabindex="-1">5. Analytics <a class="header-anchor" href="#_5-analytics" aria-label="Permalink to &quot;5. Analytics&quot;">​</a></h3><p>In-depth analysis of cumulative capital, asset allocation, and expense trends:</p><ul><li><strong>Net Worth Dynamics:</strong> monthly wealth growth chart with guaranteed continuity even if old workspaces are deleted.</li><li><strong>Asset Allocation:</strong> clear visual ratio of cash liquidity, workshops, personal property, and investments.</li><li><strong>Free Spending Trends (Burn Rate):</strong> automated lifestyle expense tracker.</li><li><strong>Onboarding Empty State:</strong> when no records exist yet, the tab displays a clean entry state with quick actions to add a first account or launch demonstration mode.</li><li><strong>🛡️ Historical Continuity &amp; Deleted Workspace Snapshots (M5):</strong> when an unused business workspace is liquidated and permanently deleted, its operational database is safely cleaned up from disk, while the system automatically preserves a compact monthly statistical snapshot in the global registry (revenue, COGS, expenses, depreciation, and net worth). This guarantees that historical Net Worth dynamics and long-term capital trends in &quot;My Capital&quot; remain continuous without artificial drop-offs or distortions for past periods.</li></ul><hr><h2 id="global-theme-modules-add-ons" tabindex="-1">Global Theme Modules (Add-ons) <a class="header-anchor" href="#global-theme-modules-add-ons" aria-label="Permalink to &quot;Global Theme Modules (Add-ons)&quot;">​</a></h2><p>In the future, <strong>Global Modules</strong>—specialized niche tools that can be purchased separately—will appear in the lower section of the sliding panel (Drawer).</p><p>They are called &quot;global&quot; because <strong>they are not tied to a specific database</strong>. For example, the &quot;Ambassador&quot; module is accessible from any active workspace, allowing you to manage promotion and affiliate campaigns for all your separate brands.</p><p>Module and status management is also centralized in the Drawer and tied to your unified license key, which &quot;evolves&quot; as you expand your ecosystem.</p>',56))])}const w=o(d,[["render",u]]);export{k as __pageData,w as default};
